jQuery(function(){var $=jQuery,$list=$("#thelist"),$btn=$("#ctlBtn"),state="pending",uploader;uploader=WebUploader.create({resize:false,server:server_url,pick:"#picker"}).on("fileQueued",function(file){$list.append('<div id="'+file.id+'" class="item">'+'<h4 class="info">'+file.name+"</h4>"+'<p class="state">等待上传...</p>'+"</div>");this.md5File(file,0,2e3*1024*1024).progress(function(percentage){var $li=$("#"+file.id);$li.find("p.state").text("上传中……"+Math.floor(percentage*100)+"%");if(percentage==1){$("#"+file.id).find("p.state").text("已上传，处理中……")}}).then(function(val){$("#"+file.id).find("p.state").text("上传成功")})});uploader.on("all",function(type){if(type==="startUpload"){state="uploading"}else if(type==="stopUpload"){state="paused"}else if(type==="uploadFinished"){state="done"}if(state==="uploading"){$btn.text("暂停上传")}else{$btn.text("开始上传")}});$btn.on("click",function(){if(state==="uploading"){uploader.stop()}else{uploader.upload()}})});
